mkdir -p $TMPDIR/scratch && cat > $TMPDIR/scratch/Scratch.java <<'EOF'
import java.util.Calendar;
import java.util.Date;
import org.apache.commons.lang.time.DateUtils;

public class Scratch {
    public static void main(String[] args) throws Exception {
        Calendar cal = Calendar.getInstance();
        cal.clear();
        cal.set(2002, Calendar.MARCH, 28, 13, 45, 1);
        cal.set(Calendar.MILLISECOND, 231);
        Date d = cal.getTime();
        System.out.println("orig: " + cal.getTime());

        Date rHour = DateUtils.round(d, Calendar.HOUR);
        System.out.println("round HOUR: " + rHour);

        Date rMonth = DateUtils.round(d, Calendar.MONTH);
        System.out.println("round MONTH: " + rMonth);

        Date tHour = DateUtils.truncate(d, Calendar.HOUR);
        System.out.println("truncate HOUR: " + tHour);

        Date tMonth = DateUtils.truncate(d, Calendar.MONTH);
        System.out.println("truncate MONTH: " + tMonth);

        // iterator month sunday example: Thursday July 4 2002
        Calendar focus = Calendar.getInstance();
        focus.clear();
        focus.set(2002, Calendar.JULY, 4);
        java.util.Iterator it = DateUtils.iterator(focus, DateUtils.RANGE_MONTH_SUNDAY);
        Calendar first = null, last = null;
        while (it.hasNext()) {
            Calendar c = (Calendar) it.next();
            if (first == null) first = c;
            last = c;
        }
        System.out.println("month sunday range first: " + first.getTime());
        System.out.println("month sunday range last: " + last.getTime());

        // semi month rounding
        Calendar sm = Calendar.getInstance();
        sm.clear();
        sm.set(2002, Calendar.MARCH, 10, 0,0,0);
        Date smRounded = DateUtils.round(sm.getTime(), DateUtils.SEMI_MONTH);
        System.out.println("semi month round(10): " + smRounded);

        Calendar sm2 = Calendar.getInstance();
        sm2.clear();
        sm2.set(2002, Calendar.MARCH, 20, 0,0,0);
        Date smRounded2 = DateUtils.round(sm2.getTime(), DateUtils.SEMI_MONTH);
        System.out.println("semi month round(20): " + smRounded2);

        Calendar sm3 = Calendar.getInstance();
        sm3.clear();
        sm3.set(2002, Calendar.MARCH, 1, 0,0,0);
        Date smRounded3 = DateUtils.round(sm3.getTime(), DateUtils.SEMI_MONTH);
        System.out.println("semi month round(1): " + smRounded3);
    }
}
EOF
javac -cp target/classes -d $TMPDIR/scratch $TMPDIR/scratch/Scratch.java
TZ=America/Los_Angeles java -cp "$TMPDIR/scratch:target/classes" Scratch
